export interface MeetingInvite {
  zoomUrl: string;
  invitationUrl: string;
}

export interface CourseConfig {
  type: string;
  date: string; // YYYY-MM-DD (start date)
  numberOfDays: number;
  duration?: string; // "HH:MM-HH:MM" (daily start-end, 24h). Default: "08:59-17:01"
  timezone?: string; // IANA timezone. Default: "America/Toronto"
  location?: string; // Default: "Virtual"
  muralLink: string;
  googleDocsFolder?: string;
  dropboxFolder?: string; // Post-course training materials link
  meetingInvite: MeetingInvite;
}

/**
 * Build the "other ways to join" block for display in emails. The one-click
 * join button (zoomUrl) is rendered separately by the template; everything
 * else (phone dial-in, dial-in passcode, SIP) lives on Zoom's own invitation
 * page, so we just link to it rather than scraping and restating it. That page
 * stays current automatically when Zoom changes a dial-in number.
 */
export function deriveMeetingInviteHtml(config: CourseConfig): string {
  const { invitationUrl } = config.meetingInvite;
  const lines = [
    `<strong>Other ways to join</strong>`,
    `<br>For phone dial-in numbers, the dial-in passcode, and other join ` +
      `options, <a href="${invitationUrl}">click here</a>.`,
  ];
  return lines.join("");
}

const DEFAULT_DURATION = "08:59-17:01";
const DEFAULT_TIMEZONE = "America/Toronto";
const DEFAULT_LOCATION = "Virtual";

const COURSE_TITLES: Record<string, string> = {
  CSM: "Certified ScrumMaster (CSM) Training",
  CSPO: "Certified Scrum Product Owner (CSPO) Training",
  CSD: "Certified Scrum Developer (CSD) Training",
};

// --- Derived fields ---

const MONTH_NAMES = [
  "Jan", "Feb", "Mar", "Apr", "May", "Jun",
  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

const DAY_NAMES = [
  "Sunday", "Monday", "Tuesday", "Wednesday",
  "Thursday", "Friday", "Saturday",
];

function parseDate(dateStr: string): Date {
  const [year, month, day] = dateStr.split("-").map(Number);
  return new Date(year, month - 1, day);
}

/** e.g. "Feb 17-18" or "Feb 28 - Mar 1" */
export function deriveDateFormatted(config: CourseConfig): string {
  const start = parseDate(config.date);
  const end = new Date(start);
  end.setDate(end.getDate() + config.numberOfDays - 1);

  const startMonth = MONTH_NAMES[start.getMonth()];
  const endMonth = MONTH_NAMES[end.getMonth()];

  if (start.getMonth() === end.getMonth()) {
    return `${startMonth} ${start.getDate()}-${end.getDate()}`;
  }
  return `${startMonth} ${start.getDate()} - ${endMonth} ${end.getDate()}`;
}

/** e.g. "20260217" */
export function deriveDateCode(config: CourseConfig): string {
  return config.date.replace(/-/g, "");
}

/** e.g. "Tuesday-Wednesday" */
export function deriveDaysOfWeek(config: CourseConfig): string {
  const start = parseDate(config.date);
  const days: string[] = [];
  for (let i = 0; i < config.numberOfDays; i++) {
    const d = new Date(start);
    d.setDate(d.getDate() + i);
    days.push(DAY_NAMES[d.getDay()]);
  }
  return days.join("-");
}

/** Derive calendar event title from course type */
export function deriveCourseTitle(config: CourseConfig): string {
  return COURSE_TITLES[config.type] || `${config.type} Training`;
}

/** Extract the Zoom join URL from the meeting invite */
export function deriveZoomLink(config: CourseConfig): string {
  return config.meetingInvite.zoomUrl;
}

// --- Calendar URL builders ---

function parseDuration(duration: string): { startH: number; startM: number; endH: number; endM: number } {
  const [startStr, endStr] = duration.split("-");
  const [startH, startM] = startStr.split(":").map(Number);
  const [endH, endM] = endStr.split(":").map(Number);
  return { startH, startM, endH, endM };
}

function pad2(n: number): string {
  return String(n).padStart(2, "0");
}

function formatLocalDateTime(date: Date, hours: number, minutes: number): string {
  return `${date.getFullYear()}${pad2(date.getMonth() + 1)}${pad2(date.getDate())}T${pad2(hours)}${pad2(minutes)}00`;
}

/** Format a 24h time as a 12h clock string, e.g. (8, 59) -> "8:59 a.m." */
function format12h(hours: number, minutes: number): string {
  const period = hours < 12 ? "a.m." : "p.m.";
  const hour12 = hours % 12 === 0 ? 12 : hours % 12;
  return `${hour12}:${pad2(minutes)} ${period}`;
}

/**
 * Derive the displayed daily class times from `duration`, e.g.
 * "8:59 a.m. to 5:01 p.m." The default duration formats to exactly that
 * string, so configs without a `duration` are unchanged.
 */
export function deriveClassTimes(config: CourseConfig): string {
  const duration = config.duration ?? DEFAULT_DURATION;
  const { startH, startM, endH, endM } = parseDuration(duration);
  return `${format12h(startH, startM)} to ${format12h(endH, endM)}`;
}

function buildEventDescription(config: CourseConfig): string {
  const { zoomUrl, invitationUrl } = config.meetingInvite;
  const lines = [
    `Zoom link: ${zoomUrl}`,
    `Other ways to join (phone / dial-in): ${invitationUrl}`,
  ];
  return lines.join("\n");
}

function eventLocation(config: CourseConfig): string {
  const location = config.location ?? DEFAULT_LOCATION;
  return location === "Virtual" ? "Virtual (Zoom)" : location;
}

/** Google Calendar "add event" URL */
export function buildGoogleCalendarUrl(config: CourseConfig): string {
  const duration = config.duration ?? DEFAULT_DURATION;
  const timezone = config.timezone ?? DEFAULT_TIMEZONE;
  const { startH, startM, endH, endM } = parseDuration(duration);
  const startDate = parseDate(config.date);
  const endDate = new Date(startDate);
  endDate.setDate(endDate.getDate() + config.numberOfDays - 1);

  const dates = `${formatLocalDateTime(startDate, startH, startM)}/${formatLocalDateTime(endDate, endH, endM)}`;

  const params = new URLSearchParams({
    action: "TEMPLATE",
    text: deriveCourseTitle(config),
    dates,
    details: buildEventDescription(config),
    location: eventLocation(config),
    ctz: timezone,
  });

  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}

/** Outlook Calendar "add event" URL */
export function buildOutlookCalendarUrl(config: CourseConfig): string {
  const duration = config.duration ?? DEFAULT_DURATION;
  const { startH, startM, endH, endM } = parseDuration(duration);
  const startDate = parseDate(config.date);
  const endDate = new Date(startDate);
  endDate.setDate(endDate.getDate() + config.numberOfDays - 1);

  const startdt = `${config.date}T${pad2(startH)}:${pad2(startM)}:00`;
  const endDateStr = `${endDate.getFullYear()}-${pad2(endDate.getMonth() + 1)}-${pad2(endDate.getDate())}`;
  const enddt = `${endDateStr}T${pad2(endH)}:${pad2(endM)}:00`;

  const params = new URLSearchParams({
    path: "/calendar/action/compose",
    rru: "addevent",
    subject: deriveCourseTitle(config),
    startdt,
    enddt,
    body: buildEventDescription(config),
    location: eventLocation(config),
    allday: "false",
  });

  return `https://outlook.live.com/calendar/deeplink/compose?${params.toString()}`;
}

