if (cliArgs.emailType !== "post") {
  if (!config.muralLink) missing.push("muralLink");
  if (!config.meetingInvite?.zoomUrl) missing.push("meetingInvite.zoomUrl");
  if (!config.meetingInvite?.invitationUrl) missing.push("meetingInvite.invitationUrl");
  // Legacy schema: passcode + dial-in numbers were replaced by a single
  // invitationUrl link to Zoom's own join page. Reject the old field so a
  // stale config breaks loudly instead of silently sending a broken invite.
  if ("passcode" in (config.meetingInvite ?? {})) {
    console.error(
      "ERROR: meetingInvite.passcode is no longer supported. Replace it with " +
        "meetingInvite.invitationUrl (the Zoom 'invitations' link that lists " +
        "dial-in numbers and the passcode).",
    );
    process.exit(1);
  }
}

