// --- Markdown template rendering ---

interface ParsedMarkdownEmail {
  subject: string;
  bodyHtml: string;
}

function parseMarkdownTemplate(mdPath: string): ParsedMarkdownEmail {
  const raw = readFileSync(mdPath, "utf-8");
  const { data, content } = matter(raw);

  if (!data.subject) {
    throw new Error(`Missing 'subject' in frontmatter of ${mdPath}`);
  }

  const bodyHtml = marked.parse(content) as string;
  return { subject: data.subject as string, bodyHtml };
}

